foundation.question_text:
$\triangle PQR$ has been translated to give the second triangle. Write a congruence statement for the two triangles.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (P) at (0,0);
\coordinate (Q) at (2.3,0.3);
\coordinate (R) at (0.8,1.6);
\coordinate (T) at (3.3,0.5);
\coordinate (U) at (5.6,0.8);
\coordinate (V) at (4.1,2.1);
\draw (P) -- (Q) -- (R) -- cycle;
\draw (T) -- (U) -- (V) -- cycle;
\node[below left] at (P) {$P$};
\node[below right] at (Q) {$Q$};
\node[above] at (R) {$R$};
\node[below left] at (T) {$T$};
\node[below right] at (U) {$U$};
\node[above] at (V) {$V$};
\end{tikzpicture}
[/tikz]

$\triangle ABC$ has been reflected in the dashed mirror line to give the second triangle. Write a congruence statement beginning $\triangle ABC \equiv \ldots$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0.3,0);
\coordinate (B) at (2.3,0);
\coordinate (C) at (1.9,1.6);
\coordinate (D) at (3.6,0);
\coordinate (E) at (5.6,0);
\coordinate (F) at (4.0,1.6);
\draw (A) -- (B) -- (C) -- cycle;
\draw (D) -- (E) -- (F) -- cycle;
\draw[dashed] (2.95,-0.5) -- (2.95,2.1);
\node[below] at (A) {$A$};
\node[below] at (B) {$B$};
\node[above] at (C) {$C$};
\node[below] at (D) {$D$};
\node[below] at (E) {$E$};
\node[above] at (F) {$F$};
\end{tikzpicture}
[/tikz]

Quadrilateral $ABCD$ has been reflected to give the second quadrilateral. Write a congruence statement beginning $ABCD \equiv \ldots$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,1.4);
\coordinate (B) at (1.5,1.4);
\coordinate (C) at (2.0,0);
\coordinate (D) at (0,0);
\coordinate (Z) at (5.5,1.4);
\coordinate (Y) at (4.0,1.4);
\coordinate (X) at (3.5,0);
\coordinate (W) at (5.5,0);
\draw (A) -- (B) -- (C) -- (D) -- cycle;
\draw (Z) -- (Y) -- (X) -- (W) -- cycle;
\node[above] at (A) {$A$};
\node[above] at (B) {$B$};
\node[below] at (C) {$C$};
\node[below] at (D) {$D$};
\node[above] at (Z) {$Z$};
\node[above] at (Y) {$Y$};
\node[below] at (X) {$X$};
\node[below] at (W) {$W$};
\end{tikzpicture}
[/tikz]

The triangles are congruent. Use the matching marks to complete the statement $\triangle GHK \equiv \triangle \ldots$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (G) at (0,0);
\coordinate (H) at (2.1,1.5);
\coordinate (K) at (2.6,0.2);
\coordinate (M) at (6.7,0);
\coordinate (N) at (5.2,2.1);
\coordinate (P) at (6.5,2.6);
\draw[tickmark] (G) -- (H);
\draw[tickmark2] (H) -- (K);
\draw[tickmark3] (G) -- (K);
\draw[tickmark] (M) -- (N);
\draw[tickmark2] (N) -- (P);
\draw[tickmark3] (M) -- (P);
\node[below left] at (G) {$G$};
\node[above left] at (H) {$H$};
\node[below right] at (K) {$K$};
\node[below] at (M) {$M$};
\node[above left] at (N) {$N$};
\node[above right] at (P) {$P$};
\end{tikzpicture}
[/tikz]

